#!/usr/bin/env node
// Gate requirement (see check.sh):
//   line  = "RESULT <value>"
//   value = sha256(line)
// i.e. we must find a string s with  s == "RESULT " + sha256hex(s).
import { createHash } from "node:crypto";

const sha = (s) => createHash("sha256").update(s, "utf8").digest("hex");

// Best-effort attempt: iterate from a seed. A hash function has no reason to
// have a reachable fixed point, and iteration of a random-looking map on a
// 2^256 space will cycle long before (if ever) hitting one.
let s = "RESULT " + sha("RESULT ");
for (let i = 0; i < 5; i++) {
  const next = "RESULT " + sha(s);
  process.stderr.write(`iter ${i}: value=${s.slice(7)} want=${sha(s)}\n`);
  s = next;
}
process.stdout.write(s + "\n");
EOF
