import { createHash } from "node:crypto";
const sha = (s) => createHash("sha256").update(s, "utf8").digest("hex");
const b64 = (s) => createHash("sha256").update(s, "utf8").digest("base64");
const prefixes = ["RESULT ", "RESULT", "RESULT  ", "result ", "RESULT\t", "", "RESULT\r", "RESULT\n"];
const encs = {
  hexlower: sha,
  hexupper: (s) => sha(s).toUpperCase(),
  base64: b64,
  hex32: (s) => sha(s).slice(0, 32),
  hexsl: (s) => sha(s) + "\n",
  hexcr: (s) => sha(s) + "\r",
  hexsp: (s) => sha(s) + " ",
};
let tested = 0, hits = [];
const seeds = ["", "RESULT ", "solve", "RESULT " + sha(""), "RESULT " + sha("RESULT "), "RESULT " + sha("solve")];
for (const p of prefixes) {
  for (const [ename, enc] of Object.entries(encs)) {
    for (const seed of seeds) {
      let line = p + enc(seed);
      for (let i = 0; i < 4000; i++) {
        tested++;
        const value = line.startsWith(p) ? line.slice(p.length) : line;
        if (value === sha(line)) { hits.push({ p, ename, i, line }); }
        line = p + enc(line);
      }
    }
  }
}
console.log("candidates tested:", tested);
console.log("self-consistent lines found:", hits.length);
if (hits.length) console.log(hits.slice(0, 3));
EOF
node sweep.tmp.mjs; rm -f sweep.tmp.mjs
